import React, { useState, useEffect } from 'react';
import { fetchApplicant } from './api/apiClient';
import './index.css';

const ApplicantDashboard = ({ applicantId, token }) => {
  const [applicant, setApplicant] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    const loadApplicant = async () => {
      setLoading(true);
      setError('');
      try {
        const res = await fetchApplicant(applicantId, token);
        setApplicant(res.data);
      } catch (err) {
        setError('Failed to load applicant data.');
      } finally {
        setLoading(false);
      }
    };
    loadApplicant();
  }, [applicantId, token]);

  if (loading) return <div>Loading...</div>;
  if (error) return <div style={{ color: 'red' }}>{error}</div>;
  if (!applicant) return <div>No applicant data found.</div>;

  return (
    <div className="dashboard-container">
      <h2>Applicant Dashboard</h2>
      <p>Welcome, {applicant.name}! Here is your submitted information and our analysis.</p>
      
      <div className="applicant-details">
        <h3>Your Information</h3>
        <p><strong>Email:</strong> {applicant.email}</p>
        <p><strong>LinkedIn:</strong> <a href={applicant.linkedin_url} target="_blank" rel="noopener noreferrer">Profile</a></p>
        
        <h3>Our Analysis</h3>
        <p><strong>Overall Rating:</strong> {applicant.insights?.rating || 'Not yet rated'}</p>
        <p><strong>Experience:</strong> {applicant.insights?.experience_years || 'Not yet calculated'} years</p>
        <p><strong>Summary:</strong> {applicant.insights?.summary || 'No summary available.'}</p>
        
        <h4>Extracted Skills:</h4>
        {applicant.resume?.structured_data?.skills ? (
          <ul>
            {applicant.resume.structured_data.skills.map((skill, index) => (
              <li key={index}>{skill}</li>
            ))}
          </ul>
        ) : <p>No skills extracted.</p>}
      </div>
    </div>
  );
};

export default ApplicantDashboard;
